 "edits": [
   {"old": "  sessionStoreFactory: {
    createHeadlessStore: (
      params?: HeadlessStoreParams,
    ) => HostSessionStore<AppState>
  }
}

export function createRuntimeHandles(
  initialState: AppState = (() => {",
    "new": "  sessionStoreFactory: {
    createHeadlessStore: (
      params?: HeadlessStoreParams,
    ) => HostSessionStore<AppState>
  }
}

type RuntimeInitialState = Pick<
  AppState,
  'toolPermissionContext' | 'mcp' | 'plugins' | 'agentDefinitions'
>

export function createRuntimeHandles(
  initialState: RuntimeInitialState = (() => {"},
   {"old": "        agentDefinitions: { activeAgents: [], allAgents: [] },
      } as AppState
    }
  })(),",
    "new": "        agentDefinitions: { activeAgents: [], allAgents: [] },
      } satisfies RuntimeInitialState
    }
  })(),"}
 ],
 "patterns": [
   {"patron": "fallback-literal-cast-to-wide-state-type",
    "senal_del_verificador": "TS2352:.*may be a mistake because neither type sufficiently overlaps",
    "fix_generico": "Cuando un `as <TipoAncho>` fuerza un objeto literal parcial de respaldo (fallback en un `catch`) a un tipo que en realidad trae muchos más campos de los que la función consume, no se ensanchan a mano los campos que faltan: se acota el tipo del parámetro/variable al subconjunto real que el cuerpo lee (`Pick<TipoAncho, 'campoA' | 'campoB'>`) y se valida el literal con `satisfies` en vez de `as`, para que TS verifique cada propiedad sin ensanchar el tipo resultante ni cambiar la forma en runtime.",
    "edits": [0, 1]}
 ],
